'use strict';
const base={alpha:.12,vol:.02,adv:20e6,n:20,t:.10,spread:5,fee:1,y:.5,p:.05,days:1,half:5};let s={...base};let A=1e7,measure='return';
const $=id=>document.getElementById(id),pct=x=>(100*x).toFixed(2)+'%',money=x=>!Number.isFinite(x)?'—':x<0?'−'+money(-x):x>=1e9?'$'+(x/1e9).toFixed(2)+'bn':x>=1e6?'$'+(x/1e6).toFixed(2)+'m':x>=1e3?'$'+(x/1e3).toFixed(1)+'k':'$'+x.toFixed(0),fixed=(x,n=3)=>Number.isFinite(x)?x.toFixed(n):'—';
function model(x,a){const g=x.alpha*2**(-(x.days-1)/(2*x.half)),f=252*x.t*(x.spread/2+x.fee)/10000,k=252*x.t*x.y*x.vol*Math.sqrt(x.t/(x.n*x.adv));const zero=g>f?((g-f)/k)**2:0,liq=x.p*x.n*x.adv/x.t,opt=Math.min(4*zero/9,liq);return {g,f,k,zero,liq,opt,cap:Math.min(zero,liq),net:g-f-k*Math.sqrt(a),impact:k*Math.sqrt(a),participation:a*x.t/(x.n*x.adv)};}
const defs=[['alpha','Gross return / year',-5,40,.5,100,'%','Excess return before execution costs'],['adv','Daily volume per asset',.1,200,.1,1/1e6,'$m','Dollar volume, not share count'],['n','Instruments',1,100,1,1,'','Equal weights and equal liquidity'],['t','Daily turnover',1,100,1,100,'%','Bought + sold notional / capital'],['vol','Daily volatility',.2,6,.1,100,'%','Daily return standard deviation'],['spread','Full bid–ask spread',0,50,.5,1,'bp','Half the spread per traded dollar'],['fee','One-way fee',0,10,.25,1,'bp','Per traded dollar'],['y','Impact factor',.1,1.5,.05,1,'','Assumed, not calibrated to fills'],['p','Volume limit',1,20,1,100,'%','Fraction of daily dollar volume']];
function controls(){$('inputDefinitions').innerHTML=defs.map(([key,name,,,,,,help])=>`<dt>${name}</dt><dd id="help-${key}">${help}</dd>`).join('');$('controls').innerHTML=defs.map(([key,name,min,max,step,scale,unit,help])=>`<div class="control"><label for="i-${key}">${name}<output id="o-${key}"></output></label><input id="i-${key}" type="range" min="${Math.min(min,s[key]*scale)}" max="${Math.max(max,s[key]*scale)}" step="${step}" value="${s[key]*scale}" aria-describedby="help-${key}"></div>`).join('');for(const [key,,,,,scale] of defs)$('i-'+key).oninput=e=>{s[key]=+e.target.value/scale;draw()};draw()}
function lineChart(datasets,{log=false,selected=null,limit=null,format=pct,label='Return',xLabel=null}={}){const compact=matchMedia('(max-width: 760px)').matches,w=compact?360:log?800:560,h=compact?290:330,l=compact?62:72,r=compact?10:22,t=24,b=47,all=datasets.flatMap(x=>x.points),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);let lo=Math.min(...ys,0),hi=Math.max(...ys,0);if(hi-lo<1e-8){hi=.01;lo=-.01}const pad=(hi-lo)*.12;hi+=pad;lo-=pad;const xmin=Math.min(...xs),xmax=Math.max(...xs),X=x=>l+(log?Math.log(x/xmin)/Math.log(xmax/xmin):(x-xmin)/(xmax-xmin||1))*(w-l-r),Y=y=>t+(hi-y)/(hi-lo)*(h-t-b);let html=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${label}"><title>${label}</title>`;if(limit&&limit<xmax){const lx=X(Math.max(xmin,limit));html+=`<rect x="${lx}" y="${t}" width="${w-r-lx}" height="${h-t-b}" fill="#eeefea"/>`;}for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;html+=`<line x1="${l}" x2="${w-r}" y1="${Y(v)}" y2="${Y(v)}" stroke="#d7d9d3" stroke-width=".8"/><text x="${l-10}" y="${Y(v)+4}" text-anchor="end" fill="#626660" font-size="12" font-family="monospace">${format(v)}</text>`}html+=`<line x1="${l}" x2="${w-r}" y1="${Y(0)}" y2="${Y(0)}" stroke="#858a80" stroke-dasharray="3 4"/>`;datasets.forEach(d=>{const path=pts=>pts.map(([x,y],i)=>`${i?'L':'M'}${X(x).toFixed(2)},${Y(y).toFixed(2)}`).join(' ');if(limit){const valid=d.points.filter(p=>p[0]<=limit),beyond=d.points.filter(p=>p[0]>limit);if(valid.length)html+=`<path d="${path(valid)}" fill="none" stroke="${d.color||'#181918'}" stroke-width="2.5"/>`;if(beyond.length)html+=`<path d="${path([...(valid.length?[valid.at(-1)]:[]),...beyond])}" fill="none" stroke="#767d70" stroke-width="2" stroke-dasharray="4 5"/>`}else html+=`<path d="${path(d.points)}" fill="none" stroke="${d.color||'#181918'}" stroke-width="${d.dash?1.5:2.5}" ${d.dash?'stroke-dasharray="5 4"':''}/>`;});for(let i=0;i<5;i++){const v=log?xmin*(xmax/xmin)**(i/4):xmin+(xmax-xmin)*i/4;html+=`<text x="${X(v)}" y="${h-15}" text-anchor="middle" fill="#626660" font-size="12" font-family="monospace">${log?money(v):xLabel?xLabel(v):'Day '+Math.round(v)}</text>`}if(selected&&selected[0]>=xmin&&selected[0]<=xmax)html+=`<line x1="${X(selected[0])}" x2="${X(selected[0])}" y1="${t}" y2="${h-b}" stroke="#181918" stroke-dasharray="3 5"/><circle cx="${X(selected[0])}" cy="${Y(selected[1])}" r="5" fill="#fafaf8" stroke="#181918" stroke-width="2.5"/>`;return html+'</svg>'}
function rows(items){return items.map(([name,value,cls=''])=>`<div class="row"><span>${name}</span><b class="${cls}">${value}</b></div>`).join('')}
function draw(){for(const [key,,,,,scale,unit] of defs)$('o-'+key).textContent=(unit==='$m'?'$':'')+(s[key]*scale).toLocaleString('en-US',{maximumFractionDigits:2})+(unit==='$m'?'m':unit?' '+unit:'');const m=model(s,A);$('capacity').textContent=money(m.cap);$('optimal').textContent=money(m.opt);$('net').textContent=pct(m.net);$('net').classList.toggle('negative',m.net<0);$('profit').textContent=money(A*m.net);$('chartHeading').textContent=measure==='profit'?'Profit vs. capital':'Return vs. capital';$('mlPresetNote').hidden=$('preset').value!=='ml';$('binding').textContent=m.zero===0?'No positive edge after fixed costs':m.liq<m.zero?'Participation limit binds first':'Return break-even binds first';$('capitalLabel').textContent=money(A);const upper=Math.min(1e12,Math.max(1e7,A*2,m.zero*1.5,m.cap*3)),lower=1e4,points=Array.from({length:141},(_,i)=>{const a=lower*(upper/lower)**(i/140);return[a,model(s,a).net*(measure==='profit'?a:1)]});$('chart').innerHTML=lineChart([{points}],{log:true,selected:[A,m.net*(measure==='profit'?A:1)],limit:m.liq,format:measure==='profit'?money:pct,label:measure==='profit'?'Modeled annual dollar profit by capital':'Modeled annual net return by capital'});const warning=m.zero===0?'No positive capacity: the gross return does not cover costs.':A>m.liq?'Volume limit exceeded. The dashed curve is an extrapolation.':m.net<0?'Trading costs exceed the gross return.':A>m.opt?'Beyond the profit maximum: more capital reduces dollar profit.':'';$('verdict').textContent=warning;$('verdict').hidden=!warning;$('waterfall').innerHTML=rows([['Return break-even',money(m.zero)],['Gross after signal delay',pct(m.g)],['Spread + fees','−'+pct(m.f)],['Market impact','−'+pct(m.impact)],['Net return',pct(m.net),m.net<0?'negative':'positive']]);const stress=model({...s,adv:s.adv*.5,vol:s.vol*1.5},A);$('stress').innerHTML=rows([['Base capacity',money(m.cap)],['Stressed capacity',money(stress.cap)],['Stressed net return',pct(stress.net),stress.net<0?'negative':''],['Current ADV participation',pct(m.participation)]]);const multipliers=[.5,.75,1,1.25,1.5];$('heatmap').innerHTML='<table><caption>Rows: gross edge multiplier · Columns: impact multiplier</caption><thead><tr><th>Edge / impact</th>'+multipliers.map(x=>`<th>${x}×</th>`).join('')+'</tr></thead><tbody>'+multipliers.map(a=>'<tr><th>'+a+'×</th>'+multipliers.map(y=>{const cap=model({...s,alpha:s.alpha*a,y:s.y*y},A).cap;return `<td style="background:rgba(80,100,62,${.025+.18*Math.min(1,cap/Math.max(m.cap*2,1))})">${money(cap)}</td>`}).join('')+'</tr>').join('')+'</tbody></table>';$('delayLabel').textContent=s.days+' days';$('halfLabel').textContent=s.half+' days'}
function route(name,scroll=false){if(!['lab','research','method','reproduce'].includes(name))name='lab';document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===name);if(a.dataset.route===name)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(scroll)document.querySelector('.section-nav').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{e.preventDefault();history.replaceState(null,'','#'+a.dataset.route);route(a.dataset.route,true)});window.addEventListener('hashchange',()=>route(location.hash.slice(1),true));document.querySelectorAll('[data-measure]').forEach(b=>b.onclick=()=>{measure=b.dataset.measure;document.querySelectorAll('[data-measure]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});draw()});$('capital').oninput=e=>{A=10**Number(e.target.value);draw()};$('delay').oninput=e=>{s.days=+e.target.value;draw()};$('half').oninput=e=>{s.half=+e.target.value;draw()};$('reset').onclick=()=>{s={...base};A=1e7;$('capital').value=7;$('preset').value='base';$('delay').value=1;$('half').value=5;controls()};function preset(value){s={...base};if(value==='small')Object.assign(s,{adv:1e6,n:8,spread:20,alpha:.18});if(value==='fast')Object.assign(s,{t:.7,alpha:.25,spread:3,half:1});if(value==='ml'){const m=RESEARCH.metrics;Object.assign(s,{alpha:m.annual_gross,t:m.daily_turnover,adv:m.adv,vol:m.daily_vol,n:1});} $('delay').value=s.days;$('half').value=s.half;controls();}$('preset').onchange=e=>preset(e.target.value);$('useML').onclick=()=>{$('preset').value='ml';preset('ml');history.replaceState(null,'','#lab');route('lab',true)};$('export').onclick=()=>{const payload={version:2,created:new Date().toISOString(),currency:'USD',assumptions:s,capital:A,results:model(s,A),warning:'Scenario model, not an investment forecast. Impact and edge are assumptions.'};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='finite-edge-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};$('copyLink').onclick=async()=>{const url=new URL('.',location.href).href;try{await navigator.clipboard.writeText(url);$('copyStatus').textContent='Portfolio link copied.'}catch{$('copyStatus').textContent=url}};
function table(headers,data){return '<table><thead><tr>'+headers.map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+data.map(row=>'<tr>'+row.map(cell=>`<td>${cell}</td>`).join('')+'</tr>').join('')+'</tbody></table>'}
function research(){const r=RESEARCH,m=r.metrics;$('mlMetrics').innerHTML=`<div><p>Test observations</p><strong>${r.test_n}</strong><span>${r.test_start} to ${r.test_end}</span></div><div><p>OOS R² vs. zero forecast</p><strong class="${m.oos_r2<0?'negative':''}">${m.oos_r2.toFixed(4)}</strong><span>Negative: zero forecast has lower MSE</span></div><div><p>Annual net, before impact</p><strong class="${m.annual_net_before_impact<0?'negative':''}">${pct(m.annual_net_before_impact)}</strong><span>5 bp full spread + 1 bp one-way fee</span></div>`;let gross=0,net=0;$('mlChart').innerHTML=lineChart([{points:r.series.map((p,i)=>[i+1,net+=p.net??p.gross-p.turnover*.00035])},{points:r.series.map((p,i)=>[i+1,gross+=p.gross]),dash:true,color:'#818779'}],{label:'Out-of-sample cumulative arithmetic gross and net return'});$('mlFinding').innerHTML=`<p>Ridge returned <b>${pct(m.annual_net_before_impact)}</b> per year after fixed trading costs in this sample, before market impact.</p><p>It did not demonstrate a profitable edge. Its forecast error was slightly higher than the zero-return baseline.</p><p>λ = ${r.selected_penalty}, selected on validation data.</p>`;$('timeline').innerHTML=`<div>Training<small>${r.train_n} observations<br>${r.train_start}<br>${r.train_end}</small></div><div>Validation<small>${r.validation_n} observations<br>ends ${r.validation_end}</small></div><div>Walk-forward test<small>${r.test_n} observations<br>${r.folds.length} refit windows<br>${r.test_end}</small></div>`;
if(r.comparison)$('comparison').innerHTML=table(['Forecast','MSE × 10⁶','OOS R²','Net / year','Turnover / day','Vol / year','Sharpe','Max DD'],r.comparison.map(c=>[c.label,fixed(c.metrics.mse*1e6,2),fixed(c.metrics.oos_r2,4),pct(c.metrics.annual_net_before_impact),pct(c.metrics.daily_turnover),pct(c.metrics.annual_volatility),fixed(c.metrics.sharpe,2),pct(c.metrics.max_drawdown)]));
if(r.uncertainty){const u=r.uncertainty;$('uncertainty').innerHTML=`<div class="interval"><small>95% interval · annual net return before impact</small><strong>${pct(u.annual_net_ci95[0])} to ${pct(u.annual_net_ci95[1])}</strong></div><div class="interval"><small>95% interval · zero-benchmark OOS R²</small><strong>${fixed(u.oos_r2_ci95[0],4)} to ${fixed(u.oos_r2_ci95[1],4)}</strong></div><p>${u.replicates.toLocaleString('en-US')} resamples · ${u.block_length}-session blocks · fixed seed</p>`;if(u.block_sensitivity)$('uncertainty').innerHTML+=table(['Block length','Net return 95% interval'],u.block_sensitivity.map(b=>[b.block_length,pct(b.annual_net_ci95[0])+' to '+pct(b.annual_net_ci95[1])]));}
$('regularization').innerHTML=table(['λ','Train MSE × 10⁶','Validation MSE × 10⁶'],r.validation_scores.map(v=>[String(v.penalty??v.lambda)+(Number(v.penalty??v.lambda)===r.selected_penalty?' ✓':''),fixed((v.train_mse??NaN)*1e6,2),fixed((v.mse??v.validation_mse)*1e6,2)]));
$('folds').innerHTML=table(['Test window','Training rows','OOS R²','Net / year','Mean |position|'],r.folds.map(f=>[`${f.test_start??f.start} – ${f.test_end??f.end}`,f.n_train??'—',fixed(f.metrics?.oos_r2,4),f.metrics?pct(f.metrics.annual_net_before_impact):'—',f.metrics?pct(f.metrics.daily_turnover/2):'—']));
if(r.ablations)$('ablations').innerHTML=table(['Omitted feature','ΔMSE × 10⁶','OOS R²'],r.ablations.map(a=>[a.label??a.feature,fixed(a.delta_mse*1e6,3),fixed(a.oos_r2,4)]));
if(r.cost_sensitivity)$('costs').innerHTML=rows(r.cost_sensitivity.map(c=>[c.one_way_bps+' bp per side',pct(c.annual_net),c.annual_net<0?'negative':'']));}
const mobileInputs=matchMedia('(max-width: 760px)');$('inputPanel').open=!mobileInputs.matches;mobileInputs.addEventListener('change',e=>{$('inputPanel').open=!e.matches;research();draw()});
research();controls();route(location.hash.slice(1));
